ALTER PROCEDURE studio.spSchedulerControl @Payload nvarchar(max) AS BEGIN  SET NOCOUNT ON; SET XACT_ABORT ON;  IF ISJSON(@Payload)<>1 BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_INPUT_INVALID' code; RETURN; END;  DECLARE @action varchar(20)=JSON_VALUE(@Payload,'$.Action'),          @owner uniqueidentifier=TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Payload,'$.UserID')),          @id uniqueidentifier=TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Payload,'$.ScheduleID')),          @target uniqueidentifier=TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Payload,'$.TargetID')),          @kind varchar(12)=JSON_VALUE(@Payload,'$.TargetType'),          @ver int=TRY_CONVERT(int,JSON_VALUE(@Payload,'$.PipelineVersion')),          @name nvarchar(150)=NULLIF(LTRIM(RTRIM(JSON_VALUE(@Payload,'$.ScheduleName'))),''),          @freq varchar(12)=JSON_VALUE(@Payload,'$.Frequency'),          @interval int=TRY_CONVERT(int,JSON_VALUE(@Payload,'$.IntervalMinutes')),          @clock char(5)=JSON_VALUE(@Payload,'$.TimeOfDay'),          @weekday tinyint=TRY_CONVERT(tinyint,JSON_VALUE(@Payload,'$.WeekDay')),          @weekmask tinyint=TRY_CONVERT(tinyint,JSON_VALUE(@Payload,'$.WeekDaysMask')),          @repeat smallint=TRY_CONVERT(smallint,JSON_VALUE(@Payload,'$.RepeatMinutes')),          @monthday tinyint=TRY_CONVERT(tinyint,JSON_VALUE(@Payload,'$.MonthDay')),          @enabled bit=TRY_CONVERT(bit,JSON_VALUE(@Payload,'$.Enabled')),          @now datetime2(3)=SYSUTCDATETIME();  IF NOT EXISTS(SELECT 1 FROM dbo.core_user WHERE user_id=@owner AND is_active=1 AND is_locked=0)  BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_ACCESS_DENIED' code; RETURN; END;  IF @action='Status'  BEGIN SELECT CAST(1 AS bit) success,'SCHEDULER_READY' code,1 schema_version; RETURN; END;  IF @action='List'  BEGIN   SELECT CAST(1 AS bit) success,'SCHEDULER_LIST' code,    (SELECT CONVERT(varchar(36),s.schedule_id) schedule_id,s.schedule_name,s.target_type,       CONVERT(varchar(36),s.target_id) target_id,s.pipeline_version,s.frequency,s.interval_minutes,       s.time_of_day,s.week_day,s.month_day,s.week_days_mask,s.repeat_minutes,s.timezone_name,s.enabled,s.next_run_at,s.last_run_at,s.updated_at,       COALESCE(d.dataset_name,p.pipeline_name) target_name     FROM studio.scheduler_schedule s     LEFT JOIN studio.dataset d ON s.target_type='STORED' AND d.dataset_id=s.target_id     LEFT JOIN studio.pipeline p ON s.target_type='PIPELINE' AND p.pipeline_id=s.target_id     WHERE studio.fnStudioScheduleAccess(@owner,s.schedule_id)>=10 AND studio.fnStudioAccessLevel(@owner,CASE WHEN s.target_type='STORED' THEN 'DATASET' ELSE 'PIPELINE' END,s.target_id)>=10 ORDER BY s.updated_at DESC,s.schedule_id     FOR JSON PATH) items_json;   RETURN;  END;  IF @action='History'  BEGIN   SELECT CAST(1 AS bit) success,'SCHEDULER_HISTORY' code,    (SELECT TOP(150) CONVERT(varchar(36),e.event_id) event_id,CONVERT(varchar(36),s.schedule_id) schedule_id,       s.schedule_name,s.target_type,COALESCE(d.dataset_name,p.pipeline_name) target_name,       e.scheduled_at,e.attempt,e.result,CONVERT(varchar(36),e.run_id) run_id,e.created_at,       COALESCE(dr.status,pr.status,e.result) status,COALESCE(dr.error_code,pr.error_code) error_code,       COALESCE(dr.finished_at,pr.finished_at) finished_at     FROM studio.scheduler_event e JOIN studio.scheduler_schedule s ON s.schedule_id=e.schedule_id     LEFT JOIN studio.dataset d ON s.target_type='STORED' AND d.dataset_id=s.target_id     LEFT JOIN studio.pipeline p ON s.target_type='PIPELINE' AND p.pipeline_id=s.target_id     LEFT JOIN studio.dataset_ingest_run dr ON s.target_type='STORED' AND dr.run_id=e.run_id     LEFT JOIN studio.pipeline_run pr ON s.target_type='PIPELINE' AND pr.run_id=e.run_id     WHERE studio.fnStudioScheduleAccess(@owner,s.schedule_id)>=10 AND studio.fnStudioAccessLevel(@owner,CASE WHEN s.target_type='STORED' THEN 'DATASET' ELSE 'PIPELINE' END,s.target_id)>=10 ORDER BY e.created_at DESC,e.event_id DESC FOR JSON PATH) items_json;   RETURN;  END;  IF @action='Save'  BEGIN   /* New weekly masks are additive; keep legacy week_day as the first selected day. */   IF @freq='WEEKLY' AND @weekmask IS NULL AND @weekday BETWEEN 1 AND 7     SET @weekmask=POWER(2,@weekday-1);   IF @freq='WEEKLY' AND @weekmask IS NOT NULL   BEGIN    SET @weekday=1;    WHILE @weekday<7 AND (@weekmask & POWER(2,@weekday-1))=0 SET @weekday=@weekday+1;   END;   IF @name IS NULL OR LEN(@name)>150 OR @target IS NULL OR @enabled IS NULL OR       @kind NOT IN ('STORED','PIPELINE') OR @freq NOT IN ('INTERVAL','DAILY','WEEKLY','MONTHLY') OR      (@freq='INTERVAL' AND (@interval IS NULL OR @interval NOT BETWEEN 5 AND 10080)) OR      (@freq<>'INTERVAL' AND (@clock IS NULL OR LEN(@clock)<>5 OR @clock NOT LIKE '[0-2][0-9]:[0-5][0-9]' OR LEFT(@clock,2)>'23')) OR      (@freq='WEEKLY' AND (@weekmask IS NULL OR @weekmask NOT BETWEEN 1 AND 127)) OR      (@freq<>'WEEKLY' AND @weekmask IS NOT NULL) OR      (@freq='DAILY' AND @repeat IS NOT NULL AND @repeat NOT BETWEEN 5 AND 1440) OR      (@freq<>'DAILY' AND @repeat IS NOT NULL) OR      (JSON_VALUE(@Payload,'$.RepeatMinutes') IS NOT NULL AND @repeat IS NULL) OR      (JSON_VALUE(@Payload,'$.WeekDaysMask') IS NOT NULL AND @weekmask IS NULL) OR      (@freq='MONTHLY' AND (@monthday IS NULL OR @monthday NOT BETWEEN 1 AND 31)) OR      (@kind='STORED' AND @ver IS NOT NULL) OR (@kind='PIPELINE' AND (@ver IS NULL OR @ver<1))   BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_INPUT_INVALID' code; RETURN; END;   IF (@kind='STORED' AND NOT EXISTS(SELECT 1 FROM studio.dataset WHERE dataset_id=@target AND access_mode='STORED' AND studio.fnStudioAccessLevel(@owner,'DATASET',dataset_id)>=20)) OR      (@kind='PIPELINE' AND NOT EXISTS(SELECT 1 FROM studio.pipeline p JOIN studio.pipeline_version v ON v.pipeline_id=p.pipeline_id AND v.version=@ver WHERE p.pipeline_id=@target AND studio.fnStudioAccessLevel(@owner,'PIPELINE',p.pipeline_id)>=20 AND JSON_QUERY(v.graph_json,'$.graph') IS NOT NULL))   BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_TARGET_NOT_FOUND' code; RETURN; END;   BEGIN TRY    BEGIN TRANSACTION; IF studio.fnStudioAccessLevel(@owner,CASE WHEN @kind='STORED' THEN 'DATASET' ELSE 'PIPELINE' END,@target)<20 THROW 52102,'SCHEDULER_NOT_FOUND',1; IF @id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM studio.scheduler_schedule WHERE schedule_id=@id AND studio.fnStudioAccessLevel(created_by,CASE WHEN @kind='STORED' THEN 'DATASET' ELSE 'PIPELINE' END,@target)>=20) THROW 52102,'SCHEDULER_NOT_FOUND',1;    IF @id IS NULL    BEGIN     IF (SELECT COUNT(*) FROM studio.scheduler_schedule WITH(UPDLOCK,HOLDLOCK) WHERE created_by=@owner)>=100        THROW 52101,'SCHEDULER_LIMIT_REACHED',1;     SET @id=NEWID();     INSERT studio.scheduler_schedule(schedule_id,created_by,schedule_name,target_type,target_id,pipeline_version,frequency,interval_minutes,time_of_day,week_day,month_day,week_days_mask,repeat_minutes,enabled,next_run_at)     VALUES(@id,@owner,@name,@kind,@target,@ver,@freq,CASE WHEN @freq='INTERVAL' THEN @interval END,        CASE WHEN @freq<>'INTERVAL' THEN @clock END,CASE WHEN @freq='WEEKLY' THEN @weekday END,CASE WHEN @freq='MONTHLY' THEN @monthday END,        CASE WHEN @freq='WEEKLY' THEN @weekmask END, CASE WHEN @freq='DAILY' THEN @repeat END, @enabled,CASE WHEN @enabled=1 THEN studio.fnSchedulerNextUtcEx(@freq,@interval,@clock,@weekday,@monthday,@now,@weekmask,@repeat) END);
        /* PHASE2D3_ATOMIC_OWNERSHIP: same transaction as schedule INSERT */
        INSERT INTO studio.object_ownership (object_type, object_id, owner_user_id)
        VALUES ('SCHEDULE', @id, @owner);
        INSERT INTO studio.object_access_audit
            (actor_user_id, object_type, object_id, action_type, new_owner_user_id)
        VALUES (@owner, 'SCHEDULE', @id, 'REGISTER', @owner);
    END
    ELSE
    BEGIN
        IF NOT EXISTS(SELECT 1 FROM studio.scheduler_schedule WITH(UPDLOCK,HOLDLOCK) WHERE schedule_id=@id AND studio.fnStudioScheduleAccess(@owner,schedule_id)>=20)         THROW 52102,'SCHEDULER_NOT_FOUND',1;     UPDATE studio.scheduler_schedule SET schedule_name=@name,target_type=@kind,target_id=@target,pipeline_version=@ver,frequency=@freq,        interval_minutes=CASE WHEN @freq='INTERVAL' THEN @interval END,        time_of_day=CASE WHEN @freq<>'INTERVAL' THEN @clock END,        week_day=CASE WHEN @freq='WEEKLY' THEN @weekday END,        month_day=CASE WHEN @freq='MONTHLY' THEN @monthday END,        week_days_mask=CASE WHEN @freq='WEEKLY' THEN @weekmask END,        repeat_minutes=CASE WHEN @freq='DAILY' THEN @repeat END,        enabled=@enabled,next_run_at=CASE WHEN @enabled=1 THEN studio.fnSchedulerNextUtcEx(@freq,@interval,@clock,@weekday,@monthday,@now,@weekmask,@repeat) END,        updated_at=@now WHERE schedule_id=@id AND studio.fnStudioScheduleAccess(@owner,schedule_id)>=20;    END;    COMMIT TRANSACTION;    SELECT CAST(1 AS bit) success,'SCHEDULER_SAVED' code,CONVERT(varchar(36),@id) schedule_id;   END TRY   BEGIN CATCH    IF @@TRANCOUNT>0 ROLLBACK;    SELECT CAST(0 AS bit) success,CASE WHEN ERROR_NUMBER()=52101 THEN 'SCHEDULER_LIMIT_REACHED' WHEN ERROR_NUMBER()=52102 THEN 'SCHEDULER_NOT_FOUND' ELSE 'SCHEDULER_SAVE_FAILED' END code;   END CATCH;   RETURN;  END;  IF @action='Toggle'  BEGIN IF NOT EXISTS(SELECT 1 FROM studio.scheduler_schedule WHERE schedule_id=@id AND studio.fnStudioScheduleAccess(@owner,schedule_id)>=20 AND studio.fnStudioAccessLevel(@owner,CASE WHEN target_type='STORED' THEN 'DATASET' ELSE 'PIPELINE' END,target_id)>=20) BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_NOT_FOUND' code; RETURN; END;   IF @id IS NULL OR @enabled IS NULL   BEGIN SELECT CAST(0 AS bit) success,'SCHEDULER_INPUT_INVALID' code; RETURN; END;   UPDATE studio.scheduler_schedule SET enabled=@enabled,     next_run_at=CASE WHEN @enabled=1 THEN studio.fnSchedulerNextUtcEx(frequency,interval_minutes,time_of_day,week_day,month_day,@now,week_days_mask,repeat_minutes) END,     updated_at=@now WHERE schedule_id=@id AND studio.fnStudioScheduleAccess(@owner,schedule_id)>=20;   IF @@ROWCOUNT=0 SELECT CAST(0 AS bit) success,'SCHEDULER_NOT_FOUND' code;   ELSE SELECT CAST(1 AS bit) success,'SCHEDULER_UPDATED' code,CONVERT(varchar(36),@id) schedule_id;   RETURN;  END;  SELECT CAST(0 AS bit) success,'SCHEDULER_ACTION_INVALID' code; END;
